4. Ein neues JavaScript-Datei namens `index.js` erstellen und folgendes Code befolgen:

   ```javascript
   const { Client, Intents } = require('discord.js');
   const client = new Client({
     intents: [
       Intents.FLAGS.GUILDS,
       Intents.FLAGS.GUILD_MESSAGES,
     ],
   });

   // Load your environment variables
   require('dotenv').config();

   // Login with your Discord bot token
   client.login(process.env.DISCORD_TOKEN);

   client.on('ready', () => {
     console.log(`Logged in as ${client.user.tag}`);
   });

   client.on('messageCreate', async message => {
     if (message.author.bot) return;
     if (!message.content.startsWith(process.env.DISCORD_CLIENT_ID + '/')) return;

     const args = message.content.slice(process.env.DISCORD_CLIENT_ID + '/'.length).trim().split(' ');
     const command = args.shift().toLowerCase();

     if (command === 'ban') {
       if (!message.member.permissions.has('BAN_MEMBERS')) {
         return message.reply('You do not have permission to ban members.');
       }

       if (!args.length) {
         return message.reply('Please provide a user to ban.');
       }

       const user = await message.guild.members.fetch(args[0]);

       if (!user.bannable) {
         return message.reply('This user cannot be banned.');
       }

       await message.guild.bans.create(user.user);

       message.reply(`Successfully banned ${user.user.tag}.`);
     }
   });
   ```

