```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <regex>

#include "Markdown.hpp" // include your preferred Markdown library

std::string convertMarkdownToHtml(const std::string& markdown) {
    std::stringstream htmlStream;
    MarkdownConverter converter;

    std::string line;
    for (const auto& ch : markdown) {
        if (ch == '\n') {
            converter.feed(line);
            line.clear();
            htmlStream << "<br/>";
        } else {
            line += ch;
        }
    }
    converter.feed(line);
    std::string html = converter.convert();

    // Replace any remaining newlines with HTML line breaks
    std::regex newlineRegex("\\n");
    html = std::regex_replace(html, newlineRegex, "<br/>");

    htmlStream << html;
    return htmlStream.str();
}

int main() {
    std::string markdown = "# Hello World\nThis is a **bold** and an _italic_ test.";
    std::string html = convertMarkdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

